              out13 => out13_sig,  -- ufix6
              out14 => out14_sig  -- ufix6
              );

  ip_timestamp <= unsigned'(X"9B3723D3");

  reset_cm <=  NOT IPCORE_RESETN;

  reset_before_sync <= reset_cm OR reset_internal;

  out1 <= out1_sig;

  out2 <= out2_sig;

